SELECT * FROM customer_package_usage_log
WHERE tenant_id = #{tenantId}
  AND customer_id = #{customerId}
ORDER BY usage_date DESC, created_at DESC

SELECT * FROM customer_package_usage_log
WHERE customer_package_id = #{customerPackageId}
ORDER BY usage_date DESC, created_at DESC

SELECT * FROM customer_package_usage_log
WHERE appointment_id = #{appointmentId}
ORDER BY usage_date DESC, created_at DESC

SELECT * FROM customer_package_usage_log
WHERE tenant_id = #{tenantId}
  AND customer_id = #{customerId}
  AND usage_date BETWEEN #{startDate} AND #{endDate}
ORDER BY usage_date DESC, created_at DESC

SELECT COUNT(*)
FROM customer_package_usage_log
WHERE tenant_id = #{tenantId}
  AND customer_id = #{customerId}
  AND usage_type = 'DEDUCT'

SELECT COUNT(*)
FROM customer_package_usage_log
WHERE tenant_id = #{tenantId}
  AND package_id = #{packageId}
  AND usage_type = 'DEDUCT'
